'use client'

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Check, Clock, MoreHorizontal } from 'lucide-react'
import { cn, formatCurrency } from '@/lib/utils'
import { toast } from 'sonner'
import type { FlashEventDetail, FlashEventSlotWithBooking } from '@/lib/flash-events/queries'

const STATUS_CONFIG: Record<
  string,
  { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline'; dot: string }
> = {
  open: { label: 'Open', variant: 'outline', dot: 'bg-primary' },
  reserved: { label: 'Reserved', variant: 'secondary', dot: 'bg-warning' },
  booked: { label: 'Booked', variant: 'default', dot: 'bg-primary' },
  blocked: { label: 'Blocked', variant: 'destructive', dot: 'bg-destructive' },
  no_show: { label: 'No-show', variant: 'outline', dot: 'bg-muted-foreground' },
}

interface Props {
  event: FlashEventDetail
  slots: FlashEventSlotWithBooking[]
  canManage: boolean
  onBlock: (slotId: string) => void
  onUnblock: (slotId: string) => void
  onWalkIn?: (slotId: string) => void
  onSendLink?: (slotId: string) => void
  onCancelReservation?: (slotId: string) => void
  onCheckIn?: (slotId: string) => void
  onNoShow?: (slotId: string) => void
  onSms?: (slotId: string) => void
  onRefund?: (slotId: string) => void
  onReopen?: (slotId: string) => void
}

export function FlashEventSlotsTab({
  event,
  slots,
  canManage,
  onBlock,
  onUnblock,
  onWalkIn,
  onSendLink,
  onCancelReservation,
  onCheckIn,
  onNoShow,
  onSms,
  onRefund,
  onReopen,
}: Props) {
  if (event.status === 'draft') {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center space-y-3">
        <div className="h-12 w-12 rounded-xl bg-muted flex items-center justify-center">
          <Clock className="h-6 w-6 text-muted-foreground" />
        </div>
        <div className="space-y-1">
          <p className="text-sm font-medium">Slots not yet generated</p>
          <p className="text-xs text-muted-foreground max-w-xs">
            Publish this event to auto-generate time slots from{' '}
            {event.start_time.slice(0, 5)} to {event.end_time.slice(0, 5)}.
          </p>
        </div>
      </div>
    )
  }

  if (slots.length === 0) {
    return (
      <p className="text-sm text-muted-foreground py-8 text-center">
        No slots found for this event.
      </p>
    )
  }

  return (
    <div className="space-y-3 max-w-2xl">
      <p className="text-xs text-muted-foreground">
        {slots.length} slot{slots.length !== 1 ? 's' : ''} — open the menu on any row to manage it
      </p>
      <div className="rounded-lg border border-border/60 overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-28">Time</TableHead>
              <TableHead>Client</TableHead>
              <TableHead className="w-24">Deposit</TableHead>
              <TableHead className="w-24">Status</TableHead>
              {canManage && <TableHead className="w-14 text-right">Actions</TableHead>}
            </TableRow>
          </TableHeader>
          <TableBody>
            {slots.map((slot) => {
              const cfg =
                STATUS_CONFIG[slot.status] ??
                STATUS_CONFIG.open ?? { label: 'Open', variant: 'outline' as const, dot: 'bg-primary' }
              const time = new Date(slot.slot_start).toLocaleTimeString('en-US', {
                hour: '2-digit',
                minute: '2-digit',
              })
              const booking = slot.booking
              const client = booking?.client
              const isNoShow = slot.status === 'no_show'

              return (
                <TableRow
                  key={slot.id}
                  className={cn(slot.status === 'blocked' && 'opacity-50')}
                >
                  <TableCell
                    className={cn(
                      'font-mono text-xs tabular-nums',
                      isNoShow && 'line-through text-muted-foreground'
                    )}
                  >
                    {time}
                  </TableCell>
                  <TableCell className="text-sm">
                    {client ? (
                      <div className="space-y-0.5">
                        <div>
                          <span className="font-medium">
                            {client.first_name} {client.last_name ?? ''}
                          </span>
                          {client.email && (
                            <span className="ml-1 text-xs text-muted-foreground">
                              · {client.email}
                            </span>
                          )}
                        </div>
                        {slot.design && (
                          <div className="text-xs text-muted-foreground">
                            ▸ {slot.design.title}
                            {slot.design.size_description && (
                              <span> ({slot.design.size_description})</span>
                            )}
                            {slot.design.price_cents != null && (
                              <span className="tabular-nums">
                                {' '}
                                · {formatCurrency(slot.design.price_cents)}
                              </span>
                            )}
                          </div>
                        )}
                      </div>
                    ) : (
                      <div className="space-y-0.5">
                        <span className="text-muted-foreground text-xs">— Open slot —</span>
                        {slot.design && (
                          <div className="text-xs text-muted-foreground">
                            ▸ {slot.design.title}
                          </div>
                        )}
                      </div>
                    )}
                  </TableCell>
                  <TableCell>
                    {booking ? (
                      booking.deposit_paid ? (
                        <span className="flex items-center gap-1 text-xs text-primary">
                          <Check className="h-3 w-3" /> Paid
                        </span>
                      ) : (
                        <span className="text-xs text-warning">Unpaid</span>
                      )
                    ) : (
                      <span className="text-xs text-muted-foreground">—</span>
                    )}
                  </TableCell>
                  <TableCell>
                    <span className="flex items-center gap-1.5">
                      <span className={cn('h-1.5 w-1.5 rounded-full', cfg.dot)} />
                      <Badge variant={cfg.variant} className="text-[10px] px-1.5">
                        {cfg.label}
                      </Badge>
                    </span>
                  </TableCell>
                  {canManage && (
                    <TableCell className="text-right">
                      <SlotActionsMenu
                        slot={slot}
                        onBlock={onBlock}
                        onUnblock={onUnblock}
                        onWalkIn={onWalkIn}
                        onSendLink={onSendLink}
                        onCancelReservation={onCancelReservation}
                        onCheckIn={onCheckIn}
                        onNoShow={onNoShow}
                        onSms={onSms}
                        onRefund={onRefund}
                        onReopen={onReopen}
                      />
                    </TableCell>
                  )}
                </TableRow>
              )
            })}
          </TableBody>
        </Table>
      </div>
    </div>
  )
}

// ── Per-row action dropdown ───────────────────────────────────────────────────

interface SlotActionsMenuProps {
  slot: FlashEventSlotWithBooking
  onBlock: (slotId: string) => void
  onUnblock: (slotId: string) => void
  onWalkIn?: (slotId: string) => void
  onSendLink?: (slotId: string) => void
  onCancelReservation?: (slotId: string) => void
  onCheckIn?: (slotId: string) => void
  onNoShow?: (slotId: string) => void
  onSms?: (slotId: string) => void
  onRefund?: (slotId: string) => void
  onReopen?: (slotId: string) => void
}

function SlotActionsMenu({
  slot,
  onBlock,
  onUnblock,
  onWalkIn,
  onSendLink,
  onCancelReservation,
  onCheckIn,
  onNoShow,
  onSms,
  onRefund,
  onReopen,
}: SlotActionsMenuProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="icon" className="h-7 w-7">
          <MoreHorizontal className="h-3.5 w-3.5" />
          <span className="sr-only">Open slot actions</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        {slot.status === 'open' && (
          <>
            <DropdownMenuItem
              onSelect={() =>
                onWalkIn
                  ? onWalkIn(slot.id)
                  : toast.info('Walk-in coming next pass')
              }
            >
              Mark walk-in
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem onSelect={() => onBlock(slot.id)}>
              Block slot
            </DropdownMenuItem>
          </>
        )}
        {slot.status === 'reserved' && (
          <>
            <DropdownMenuItem
              onSelect={() =>
                onSendLink
                  ? onSendLink(slot.id)
                  : toast.info('Reminder dispatch coming in phase 3d')
              }
            >
              Send link
            </DropdownMenuItem>
            <DropdownMenuItem
              onSelect={() =>
                onCancelReservation
                  ? onCancelReservation(slot.id)
                  : toast.info('Cancel reservation — phase 3d')
              }
            >
              Cancel reservation
            </DropdownMenuItem>
          </>
        )}
        {slot.status === 'booked' && (
          <>
            <DropdownMenuItem
              onSelect={() =>
                onCheckIn
                  ? onCheckIn(slot.id)
                  : toast.info('Check-in coming next')
              }
            >
              Mark checked-in
            </DropdownMenuItem>
            <DropdownMenuItem
              onSelect={() =>
                onNoShow
                  ? onNoShow(slot.id)
                  : toast.info('No-show coming next')
              }
            >
              Mark no-show
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              onSelect={() =>
                onSms
                  ? onSms(slot.id)
                  : toast.info('SMS coming next')
              }
            >
              Send SMS reminder
            </DropdownMenuItem>
            <DropdownMenuItem
              disabled={!slot.booking?.deposit_paid}
              onSelect={() =>
                onRefund
                  ? onRefund(slot.id)
                  : toast.info('Refund coming next')
              }
            >
              Refund deposit
            </DropdownMenuItem>
          </>
        )}
        {slot.status === 'blocked' && (
          <DropdownMenuItem onSelect={() => onUnblock(slot.id)}>
            Unblock slot
          </DropdownMenuItem>
        )}
        {slot.status === 'no_show' && (
          <DropdownMenuItem
            onSelect={() =>
              onReopen
                ? onReopen(slot.id)
                : toast.info('Reopen coming next')
            }
          >
            Reopen slot
          </DropdownMenuItem>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

